Lemma popfree_facts_sound : forall E M lb lk cnt c s K (base : word),
  bv_unsigned base = estart E (SA lb lk) ->
  (K <= Z.to_nat cnt)%nat -> 0 < cnt -> estart E (SA lb lk) + 4 * cnt <= 2 ^ 64 -> 0 <= estart E (SA lb lk) ->
