  AsanHeapSort.RECS n tbl -> 0 <= T -> T + 16 * Z.of_nat n <= 2 ^ 64 ->
  (forall j, 0 <= j < 16 * Z.of_nat n -> rdn SEGS M' (Z_to_bv 64 (T + j)) 1 = Some [Z_to_bv 8 (AsanHeapSort.tbyte tbl j)]) ->
  know_ok SEGS E M' (hs_facts T (AsanHeapSortDef.hs_words tbl)).
Proof.
