Lemma kwidx_fold : forall T L k0 l t,
  (forall K, In K l -> In K k0) ->
  (forall q w v, tget q t = Some (w, v) ->
     exists v0, In (KWord (SA (ELit 0) (T + Zpos q - 1)) w (ELit v0)) k0 /\ v = v0 mod two64 /\ T <= T + Zpos q - 1 < T + L) ->
  forall q w v, tget q (fold_left (fun t K => match K with
                        | KWord (SA (ELit 0) a) w (ELit v) =>
                            if (Z.leb T a && Z.ltb a (T + L))%bool then tset (Z.to_pos (a - T + 1)) (w, v mod two64) t else t
                        | _ => t
                        end) l t) = Some (w, v) ->
     exists v0, In (KWord (SA (ELit 0) (T + Zpos q - 1)) w (ELit v0)) k0 /\ v = v0 mod two64 /\ T <= T + Zpos q - 1 < T + L.
