Lemma idx_byte_go_sound : forall E M k T L j d b,
  know_ok SEGS E M k -> 0 <= T -> T + L <= 2 ^ 64 -> 0 <= j ->
  idx_byte_go (kwidx T L k) j d = Some b ->
