Lemma hs_table_sound : forall E M k T L tz,
  know_ok SEGS E M k -> hs_table SEGS k T L = Some tz -> 0 <= T -> 0 <= L -> T + L <= 2 ^ 64 ->
  length tz = Z.to_nat L /\ AsanHeapSort.bytes_ok tz
  /\ forall j, 0 <= j < L -> rdn SEGS M (Z_to_bv 64 (T + j)) 1 = Some [Z_to_bv 8 (nth (Z.to_nat j) tz 0)].
Proof.
